insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D8-S1-001', 'source'::public.t3a_content_family, 'The figures sent from the wrong file', 'D8', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D8-S1-001", "title": "The figures sent from the wrong file", "stage": 1, "stage_code": "S1", "demonstration": true, "serving_eligible": false, "scenario_class": "observation_ready", "d8_situation_class": "SC-D8-1", "interaction_pattern_family_id": "IPF-D8-01", "administration_form_id": "AF-S1-SEQUENTIAL-REVEAL", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"setback_established": "In the situation: \"three figures do not match their own records.\"", "containment_actions": "CA1 send the corrected pack from the released file. CA2 tell the client which three lines differ and which version is correct. CA3 check the two earlier packs built from the working file.", "corrective_actions": "CR1 check the two earlier packs built from the working file. CR2 build the pack only from the released file from now on.", "designated_facts": "DF1 which three lines differ and by how much. DF2 which file the pack was built from. DF3 how far the pack has been forwarded. DF4 whether the two earlier packs carry the same difference.", "available_supports": "SU1 the client''s analyst who raised it. SU2 the owner of the released file. SU3 the participant''s manager.", "standing_commitments": "CM1 the corrected pack by end of day. CM2 the monthly pack cycle.", "work_in_progress": "WP1 the current month''s pack. WP2 the two earlier packs already issued.", "recurrence_measures": "RM1 the pack built only from the released file. RM2 a source-file check before any pack is sent.", "recurring_condition": "The working file has been used twice before without the difference arising.", "formal_record_state": "None.", "record_place": "The client reporting log.", "who_knows": "The client''s analyst and four recipients, retained, never rendered.", "decision_origin": "None.", "account_test_point": "R8.", "account_test_record": "The situation records that the pack has been forwarded inside the client organization to four people.", "unsupported_inferences": "That the participant was careless; ANY OBSERVATION OF HOW THE ERROR WAS TAKEN, INCLUDING THAT IT SEEMED NOT TO REGISTER.", "irrelevant_conduct": "Who is answerable, WHICH IS A D2 MATTER; the client''s analyst.\n\n| Question | State | Basis |\n|---|---|---|\n| Q-D8-01 | DIRECT | Three containment actions |\n| Q-D8-01b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-02 | DIRECT | Four designated facts |\n| Q-D8-02b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-03 | DIRECT | Two actions on the condition |\n| Q-D8-03b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-04 | DIRECT | Three supports |\n| Q-D8-04b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-05 | DIRECT | Two standing commitments |\n| Q-D8-05b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-06 | DIRECT | Two items of work under way |\n| Q-D8-06b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-07 | DIRECT | Two measures against the condition arising again |\n| Q-D8-07b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-08 | DIRECT | A record place exists |\n| Q-D8-09 | DIRECT | The account test at R8 puts an earlier statement back |", "d8_situation_class": "SC-D8-1"}, "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "Three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "Four designated facts"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "Two actions on the condition"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "Three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "Two standing commitments"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "Two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "Two measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "A record place exists"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test at R8 puts an earlier statement back"}], "script": null, "reveals": [], "text_blocks": {"The situation as the participant meets it": "You prepare the monthly figures pack for a client. Yesterday you sent it and this morning the client''s analyst replied that three figures do not match their own records.\nWhat the record shows: you built the pack from a working file rather than the released file, and the two differ on three lines; the released file is unchanged and correct; the pack has been forwarded inside the client organization to four people; the working-file version has been used for the pack twice before without the difference arising; and the client''s analyst has asked for a corrected pack by end of day."}, "narrative": {"The situation as the participant meets it": "> You prepare the monthly figures pack for a client. Yesterday you sent it and this morning the client''s analyst replied that three figures do not match their own records.\n>\n> What the record shows: you built the pack from a working file rather than the released file, and the two differ on three lines; the released file is unchanged and correct; the pack has been forwarded inside the client organization to four people; the working-file version has been used for the pack twice before without the difference arising; and the client''s analyst has asked for a corrected pack by end of day.", "Reveal sequence": "R1 the situation. R2 QUESTION: what is the first thing you do, and about what? R3 QUESTION: what do you establish before you do anything further? R4 QUESTION: what do you do about the thing that allowed it? R5 QUESTION: whose help or what resource do you go to, if any? R6 QUESTION: what still gets met, and what work resumes and from when? R7 QUESTION: what do you do about it happening again, and what gets written down and where? R8 ACCOUNT TEST: your manager writes, \"You said the pack had not been forwarded. Had it?\" — QUESTION: what do you say?", "What this fixture proves": "Every D8 element is served from a written response, and every entry it can produce records what the participant stated or named. A build that withholds an element at Stage 1, or that lets a performed-act verb into any D8 entry, has failed Section 5.7."}, "source_version_hash": "44d6ede4bd6647335f1b727b52ccb9a00ad52ee2688bef45dc172dabc47317ae"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D8-S1-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
