insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D8-S2-001', 'source'::public.t3a_content_family, 'The report that was signed without the check', 'D8', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D8-S2-001", "title": "The report that was signed without the check", "stage": 2, "stage_code": "S2", "demonstration": true, "serving_eligible": false, "scenario_class": "observation_ready", "d8_situation_class": "SC-D8-3", "interaction_pattern_family_id": "IPF-D8-03", "administration_form_id": "AF-S2-SEVEN-BEAT", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"setback_established": "In the pre-brief: \"issued without its second-reviewer check.\"", "containment_actions": "CA1 hold the report due in four days pending the second review. CA2 make the second reviewer a system gate rather than a checklist item. CA3 re-review the six reports carrying the pattern.", "corrective_actions": "CR1 make the second reviewer a system gate rather than a checklist item. CR2 re-review the six reports carrying the pattern.", "designated_facts": "DF1 what the procedure requires and what the record shows. DF2 how many of the last thirty carry the same pattern. DF3 that the reports have not been found inaccurate. DF4 what the audit response requires and by when.", "available_supports": "SU1 the audit lead, available now. SU2 the named second reviewer. SU3 the procedure owner who controls the system gate.", "standing_commitments": "CM1 the written audit response within ten business days. CM2 the report due in four days. CM3 the two-reviewer requirement itself.", "work_in_progress": "WP1 the report due in four days. WP2 the six reports carrying the pattern.", "recurrence_measures": "RM1 the second reviewer enforced as a system gate. RM2 the six prior reports re-reviewed and recorded. RM3 a monthly completeness check on reviewer records.", "recurring_condition": "Six of the last thirty carry the same pattern.", "formal_record_state": "The audit finding.", "record_place": "The audit response register.", "who_knows": "The audit lead, retained, never rendered.", "decision_origin": "None.", "account_test_point": "B6.", "account_test_record": "The situation records that the same single-reviewer pattern appears on six of the last thirty reports.", "unsupported_inferences": "Who omitted the check, WHICH IS A D2 MATTER; ANY OBSERVATION OF HOW THE FINDING WAS RECEIVED.", "irrelevant_conduct": "The audit lead; the second reviewer.\n\n| Question | State | Basis |\n|---|---|---|\n| Q-D8-01 | DIRECT | Three containment actions |\n| Q-D8-01b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-02 | DIRECT | Four designated facts |\n| Q-D8-02b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-03 | DIRECT | Two actions on the condition |\n| Q-D8-03b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-04 | DIRECT | Three supports |\n| Q-D8-04b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-05 | DIRECT | Three standing commitments |\n| Q-D8-05b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-06 | DIRECT | Two items of work under way |\n| Q-D8-06b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-07 | DIRECT | Three measures against the condition arising again |\n| Q-D8-07b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-08 | DIRECT | A record place exists |\n| Q-D8-09 | DIRECT | The account test at B6 puts an earlier statement back |", "d8_situation_class": "SC-D8-3"}, "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "Three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "Four designated facts"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "Two actions on the condition"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "Three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "Three standing commitments"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "Two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "Three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "A record place exists"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test at B6 puts an earlier statement back"}], "script": null, "reveals": [], "text_blocks": {}, "narrative": {"Participant pre-brief": "An internal audit has found that a compliance report you sign was issued without its second-reviewer check. What the record shows: the procedure requires two reviewers and the record shows one; the same single-reviewer pattern appears on six of the last thirty reports; the reports themselves have not been found inaccurate; the audit requires a written response within ten business days; the next report is due in four days; and the audit lead is available now.", "Mentor brief": "The mentor reads the scripted lines of the audit lead. **THE MENTOR FORMS NO VIEW OF HOW THE PARTICIPANT IS TAKING THE FINDING AND RECORDS NOTHING ABOUT IT, INCLUDING THAT THEY SEEMED UNTROUBLED.**", "The four questions": "B3 — \"What have you done since the finding, and what do you know?\" B4 — \"What are you doing about the check itself, and who are you going to?\" B5 — \"What still gets met, what continues and from when, what stops this recurring, and what goes on the record?\" B6 — \"Just so I have it right — you said this was the only report affected. Is it?\"", "What this fixture proves": "Two things. The action \"make the second reviewer a system gate rather than a checklist item\" appears in containment_actions and in corrective_actions: selected in Q-D8-01b and in Q-D8-03b, it composes once in each control, because one act serving two purposes is two facts, and neither is suppressed as a duplicate. And the mentor records only what the participant states about the work: nothing observed about the person is recordable, including that they seemed untroubled."}, "source_version_hash": "1fa168b3df8c5f75578962ceb19b4a212d3dc35bd073d6a75d37b60f1ae98b55"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D8-S2-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
insert into public.t3a_source_authorship(source_version_id, source_author_identity) select v.content_version_id, array['DEMONSTRATION_AUTHOR'] from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D8-S2-001' on conflict do nothing;
