insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 2, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D8-S2-001' on conflict do nothing;
insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D8-S3-001', 'source'::public.t3a_content_family, 'The pilot that closed at forty percent', 'D8', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D8-S3-001", "title": "The pilot that closed at forty percent", "stage": 3, "stage_code": "S3", "demonstration": true, "serving_eligible": false, "scenario_class": "work_sample", "d8_situation_class": "SC-D8-4", "interaction_pattern_family_id": "IPF-D8-04", "administration_form_id": "AF-S3-ASYNC-SUBMISSION", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"setback_established": "In the brief: \"closed with forty percent of its intended throughput.\"", "containment_actions": "CA1 set this pilot''s throughput against its two predecessors. CA2 hold the five-week rollout pending the pilot''s figures. CA3 survey the pilot''s participants.", "corrective_actions": "CR1 remove or document the rationale for the introduced step. CR2 hold the five-week rollout pending the pilot''s figures.", "designated_facts": "DF1 this pilot''s throughput against the two predecessors. DF2 that the single difference is one introduced process step. DF3 that the step carries no documented rationale. DF4 what the five-week rollout assumes.", "available_supports": "SU1 the program board at the three-week review. SU2 the two predecessor pilots'' records. SU3 the pilot''s participants, not yet surveyed.", "standing_commitments": "CM1 the rollout beginning in five weeks. CM2 the board outcome review in three weeks.", "work_in_progress": "WP1 the five-week rollout preparation. WP2 the introduced process step.", "recurrence_measures": "RM1 any process change carrying a documented rationale before use. RM2 a throughput threshold that pauses rollout. RM3 participant survey run at every pilot close.", "recurring_condition": "Two predecessors at eighty-five and ninety percent make this a departure from an established pattern.", "formal_record_state": "The pilot''s closing figures.", "record_place": "The program outcome record.", "who_knows": "The program board, retained, never rendered.", "decision_origin": "None.", "unsupported_inferences": "Who introduced the step, WHICH IS A D2 MATTER; ANYTHING ABOUT THE PILOT''S PARTICIPANTS OR THEIR REASONS.", "irrelevant_conduct": "Whether the step was a good idea; the board''s expectations.\n\n| Question | State | Basis |\n|---|---|---|\n| Q-D8-01 | DIRECT | Three containment actions |\n| Q-D8-01b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-02 | DIRECT | Four designated facts |\n| Q-D8-02b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-03 | DIRECT | Two actions on the condition |\n| Q-D8-03b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-04 | DIRECT | Three supports |\n| Q-D8-04b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-05 | DIRECT | Two standing commitments |\n| Q-D8-05b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-06 | DIRECT | Two items of work under way |\n| Q-D8-06b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-07 | DIRECT | Three measures against the condition arising again |\n| Q-D8-07b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-08 | DIRECT | A record place exists |\n| Q-D8-09 | NOT SERVED | The asynchronous form puts no earlier statement back. NO ANSWER ROW, NO MISSING-STATE CODE |", "d8_situation_class": "SC-D8-4"}, "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "Three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "Four designated facts"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "Two actions on the condition"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "Three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "Two standing commitments"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "Two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "Three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "A record place exists"}, {"question": "Q-D8-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back. NO ANSWER ROW, NO MISSING-STATE CODE"}], "script": null, "reveals": [], "text_blocks": {"The brief as the participant meets it": "A pilot you ran has closed with forty percent of its intended throughput.\nWhat the record shows: the pilot''s two predecessors closed at eighty-five and ninety percent; the difference between them is a single process step introduced for this pilot; the step was introduced without a documented rationale; the full rollout is scheduled to begin in five weeks and is unchanged; the pilot''s participants have not been surveyed; and the program board reviews outcomes in three weeks.\nProduce: what you would do first and what you would establish; what you would do about the condition and whose help you would seek; what still gets met, what continues and from when; and what you would do about a recurrence and what would be recorded where."}, "narrative": {"The brief as the participant meets it": "> A pilot you ran has closed with forty percent of its intended throughput.\n>\n> What the record shows: the pilot''s two predecessors closed at eighty-five and ninety percent; the difference between them is a single process step introduced for this pilot; the step was introduced without a documented rationale; the full rollout is scheduled to begin in five weeks and is unchanged; the pilot''s participants have not been surveyed; and the program board reviews outcomes in three weeks.\n>\n> Produce: what you would do first and what you would establish; what you would do about the condition and whose help you would seek; what still gets met, what continues and from when; and what you would do about a recurrence and what would be recorded where.", "Submission": "Asynchronous. `min_seconds`, `max_seconds` and `mentor_action_sequence` NULL — null is not an error. Eleven provenance fields, three declarations, AI_USE_DECLARATION_REQUIRED in force.", "What this fixture proves": "Q-D8-09 produces no row of any kind while the other eight elements are served from the submission. A build that writes a null, a `not_applicable` or a \"not observed\" sentence for Q-D8-09 has failed."}, "source_version_hash": "06f7cda37242dfd005a47ee79c5049a1a914cf656cb1447fe8b450781741f4ce"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D8-S3-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
