insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D8-S4-001", "title": "The interface that failed at handover", "stage": 4, "stage_code": "S4", "demonstration": true, "serving_eligible": false, "scenario_class": "team_simulation", "d8_situation_class": "SC-D8-6", "interaction_pattern_family_id": "IPF-D8-06", "administration_form_id": "AF-S4-GROUP-ROUND", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"setback_established": "In the pre-brief: \"failed on the first day of live running and the group has reverted to manual processing.\"", "containment_actions": "CA1 confirm what the failing transaction type is and how often it occurs. CA2 add the missing transaction type to the test data set. CA3 set the three-day fix against the steering group''s four days.", "corrective_actions": "CR1 add the missing transaction type to the test data set. CR2 re-test the four prior handovers against the extended set.", "designated_facts": "DF1 which transaction type failed and its frequency. DF2 that the test data set omits it. DF3 that the same set has been used for four prior handovers. DF4 what the fix takes against the steering group date.", "available_supports": "SU1 the operations group carrying the manual load. SU2 the testing function holding the data set. SU3 the steering group in four days.", "standing_commitments": "CM1 the operations group''s daily processing. CM2 the steering group position in four days. CM3 the four prior handovers already live.", "work_in_progress": "WP1 the failed interface. WP2 the four prior handovers.", "recurrence_measures": "RM1 the test data set extended to every transaction type. RM2 the four prior handovers re-tested. RM3 test data coverage confirmed before any handover.", "recurring_condition": "The same incomplete test data set used for four prior handovers.", "formal_record_state": "The test cycle pass record.", "record_place": "The handover defect log.", "who_knows": "Operations, testing and the steering group, retained, never rendered.", "decision_origin": "None.", "account_test_point": "B6.", "account_test_record": "The situation records that the test data set does not include the transaction type that failed.", "unsupported_inferences": "Who built the test set, WHICH IS A D2 MATTER; ANY COMPARISON OF WHAT P-OBS SAID AT B3 WITH B6 TO INFER WHETHER THEY HELD UP; any observation of the room.", "irrelevant_conduct": "The co-participants'' statements; the operations group''s inconvenience.\n\n| Question | State | Basis |\n|---|---|---|\n| Q-D8-01 | DIRECT | Three containment actions |\n| Q-D8-01b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-02 | DIRECT | Four designated facts |\n| Q-D8-02b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-03 | DIRECT | Two actions on the condition |\n| Q-D8-03b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-04 | DIRECT | Three supports |\n| Q-D8-04b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-05 | DIRECT | Three standing commitments |\n| Q-D8-05b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-06 | DIRECT | Two items of work under way |\n| Q-D8-06b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-07 | DIRECT | Three measures against the condition arising again |\n| Q-D8-07b | CONDITIONAL | Served once its parent records a serving answer |\n| Q-D8-08 | DIRECT | A record place exists |\n| Q-D8-09 | DIRECT | The account test at B6 puts an earlier statement back |", "d8_situation_class": "SC-D8-6"}, "question_applicability": [{"question": "Q-D8-01", "state": "DIRECT", "basis": "Three containment actions"}, {"question": "Q-D8-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-02", "state": "DIRECT", "basis": "Four designated facts"}, {"question": "Q-D8-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-03", "state": "DIRECT", "basis": "Two actions on the condition"}, {"question": "Q-D8-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-04", "state": "DIRECT", "basis": "Three supports"}, {"question": "Q-D8-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-05", "state": "DIRECT", "basis": "Three standing commitments"}, {"question": "Q-D8-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-06", "state": "DIRECT", "basis": "Two items of work under way"}, {"question": "Q-D8-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-07", "state": "DIRECT", "basis": "Three measures against the condition arising again"}, {"question": "Q-D8-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D8-08", "state": "DIRECT", "basis": "A record place exists"}, {"question": "Q-D8-09", "state": "DIRECT", "basis": "The account test at B6 puts an earlier statement back"}], "script": null, "reveals": [], "text_blocks": {}, "narrative": {"Model": "ONE OBSERVED PARTICIPANT (P-OBS), THREE CO-PARTICIPANTS (CP-1, CP-2, CP-3) who are role players and are NOT observed, one facilitator. ONE OBSERVATION RECORD, for P-OBS only. A Stage 4 group participation record is required for all four before entry. No recording.", "P-OBS pre-brief": "A system interface your team hands over to an operations group failed on the first day of live running and the group has reverted to manual processing. What the record shows: the interface passed its test cycle; the test data set does not include the transaction type that failed; the same test data set has been used for the last four handovers; manual processing costs the operations group about six hours a day; a fix is estimated at three days; and the steering group meets in four days.", "CP positions": "CP-1, operations: state the six hours a day of manual processing. CP-2, testing: state that the interface passed its test cycle. CP-3, the steering group''s office: state the four-day meeting date.", "Facilitator card": "As Section 5.18, including: **RECORD ONLY WHAT WAS SAID AND DONE ABOUT THE WORK. NOTHING ABOUT ANY PERSON IN THE ROOM IS RECORDABLE, INCLUDING THE ABSENCE OF A REACTION.**", "The four questions": "B3 — \"What has been done since the failure, and what do we know?\" B4 — \"What are we doing about the test data set, and who are we going to?\" B5 — \"What still gets met, what continues and from when, what stops this recurring, and what goes on the record?\" B6 — \"Just so the position is right — you said the test set covers every transaction type. Does it?\"", "What this fixture proves": "All three co-participants restate facts the pre-brief already establishes: the manual hours, the test pass, the meeting date. **THE PRE-BRIEF AND SOURCE SHEET ESTABLISH THEM; THE CO-PARTICIPANTS DO NOT.** A build that lets a co-participant position populate `containment_actions`, `corrective_actions`, `designated_facts` or `standing_commitments` will pass the other three fixtures and fail here."}, "source_version_hash": "a69c95ae7ce0175f3b63eed81de037d2094e2c7ab75ca2a73dd3db3b59efea37"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D8-S4-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
insert into public.t3a_source_authorship(source_version_id, source_author_identity) select v.content_version_id, array['DEMONSTRATION_AUTHOR'] from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D8-S4-001' on conflict do nothing;
